use maho_rpc::{session_worker_client::settle_output_credit,session_worker_signals::WorkerSignal};
#[tokio::test]async fn output_credit_is_released_only_after_consumption(){let signal=WorkerSignal::default();let(started,observed)=tokio::sync::oneshot::channel();let(release,consumed)=tokio::sync::oneshot::channel();let pending=async{started.send(()).unwrap();consumed.await.unwrap();Ok(())};let settle=settle_output_credit(&signal,pending,|_|panic!("accepted output failed"));let verify=async{observed.await.unwrap();assert_eq!(signal.wait(std::time::Duration::ZERO),0);release.send(()).unwrap();};tokio::time::timeout(std::time::Duration::from_secs(2),async{tokio::join!(settle,verify)}).await.unwrap();assert_eq!(signal.wait(std::time::Duration::ZERO),1);}
#[tokio::test]async fn output_failure_denies_credit_before_failure_callback(){let signal=WorkerSignal::default();let failed=std::cell::Cell::new(false);settle_output_credit(&signal,async{Err("closed output".into())},|error|{assert_eq!(error,"closed output");assert_eq!(signal.wait(std::time::Duration::ZERO),2);failed.set(true);}).await;assert!(failed.get());}
